'use strict';
const DUTY_SCENES={
 patrol:{art:4,place:'The outer watchtowers',intro:'Lanterns flicker along the village wall. A scout offers two paths for tonight’s watch.',enemy:'Rogue rooftop scout',discovery:'An abandoned watch post',detail:'A torn supply pouch lies beneath the watchtower. Stop to search it, or keep moving?'},
 archive:{art:18,place:'The sealed archives',intro:'A forbidden shelf has been disturbed. Choose how to secure the archive before your shift.',enemy:'Masked scroll thief',discovery:'An unmarked scroll',detail:'You uncover an old cipher tucked inside a ledger. Study it, or return it to the vault?'},
 escort:{art:33,place:'The mist road',intro:'The caravan reaches a fork in the road. The merchants await your route decision.',enemy:'Mist-road raider',discovery:'A stranded merchant',detail:'A merchant needs help recovering a crate. Help them, or focus on your caravan?'}
};
function dutyNote(text){s.duty.journal.unshift({text,time:Date.now()});s.duty.journal=s.duty.journal.slice(0,18)}
function migrateDuty(){if(!s.duty||s.duty.version===2)return;const d=dutyTypes.find(d=>d.id===s.duty.id);if(!d){s.duty=null;return}const elapsed=Math.min(d.duration,Math.max(0,d.duration-(s.duty.ends-Date.now())));s.duty={...s.duty,version:2,elapsed,lastTick:Date.now(),stage:3,event:null,bonusCoins:0,bonusXp:0,cautious:false,journal:[{text:'Your existing assignment is preserved. Interactive encounters begin with your next duty.',time:Date.now()}]};save()}
startDuty=function(id){regen();const d=dutyTypes.find(d=>d.id===id);if(!d||s.duty||s.hp<=0||s.stamina<d.cost)return false;s.stamina-=d.cost;s.duty={id,version:2,elapsed:0,lastTick:Date.now(),ends:Date.now()+d.duration,stage:0,event:{type:'route'},bonusCoins:0,bonusXp:0,cautious:false,journal:[]};dutyNote('Assignment started. Choose your approach.');s.lastDuty=null;return true};
function advanceDuty(now=Date.now()){migrateDuty();const j=s.duty;if(!j)return false;const d=dutyTypes.find(d=>d.id===j.id);if(j.event){j.lastTick=now;return false}const previous=j.elapsed,limit=j.stage===1?d.duration*.35:j.stage===2?d.duration*.7:d.duration;j.elapsed=Math.min(limit,j.elapsed+Math.max(0,now-j.lastTick));j.lastTick=now;j.ends=now+d.duration-j.elapsed;
 if(j.elapsed>=limit&&j.stage<3){const scene=DUTY_SCENES[j.id];if(j.stage===1){const hp=Math.min(80,40+s.level*2);j.event={type:'ambush',name:scene.enemy,hp,maxHp:hp,attack:18+s.level*2,defense:15+s.level*2};dutyNote(scene.enemy+' ambushed you!')}else{j.event={type:'discovery'};dutyNote(scene.discovery+' — decide what to do.')}save();return true}
 if(j.elapsed!==previous)save();return previous<d.duration&&j.elapsed>=d.duration;
}
function finishDutyEvent(){const j=s.duty;j.event=null;j.stage++;j.lastTick=Date.now();j.ends=Date.now()+dutyTypes.find(d=>d.id===j.id).duration-j.elapsed}
function failDuty(text){const j=s.duty;s.lastDuty={name:dutyTypes.find(d=>d.id===j.id).name,success:false,text,journal:j.journal};log(text);s.duty=null;toast(text)}
function dutyChoice(action){advanceDuty();const j=s.duty;if(!j)return false;const e=j.event;
 if(action==='retreat'){failDuty('Duty abandoned. No rewards earned; spent stamina is not refunded.');return true}
 if(!e)return false;
 if(s.hp<=0){toast('Visit the doctor before continuing this duty.');return false}
 if(e.type==='route'&&['cautious','bold'].includes(action)){j.cautious=action==='cautious';if(!j.cautious)j.bonusCoins+=30;dutyNote(j.cautious?'You scout ahead: ambush damage reduced by 35%.':'You take the direct route: +30 Copper if you complete the duty.');finishDutyEvent();return true}
 if(e.type==='discovery'&&['investigate','continue'].includes(action)){if(action==='investigate'){if(s.energy<5){toast('You need 5 Spirit to investigate.');return false}s.energy-=5;j.bonusCoins+=40;j.bonusXp+=8;dutyNote('You investigate with spirit sensing: +40 Copper and +8 XP on completion.')}else dutyNote('You secure the area and continue your assignment.');finishDutyEvent();return true}
 if(e.type!=='ambush'||!['fight','jutsu','evade'].includes(action))return false;
 if(action==='jutsu'&&(s.energy<8||!Object.values(s.tech).some(n=>n>0))){toast('Learn a jutsu and have 8 Spirit to use it here.');return false}
 if(action==='evade'&&Math.random()<.7){dutyNote('You slip past the attacker and continue unharmed.');finishDutyEvent();return true}
 const p=power();if(action==='jutsu')s.energy-=8;
 const dealt=action==='evade'?0:Math.min(e.hp,27,Math.max(5,Math.round((p.a*(action==='jutsu'?1.4:1)-e.defense*.25)*(.85+Math.random()*.3)*.4)));
 const taken=Math.min(s.hp,27,Math.max(1,Math.round((e.attack*.55-p.d*.1)*(j.cautious?.65:1)*(.85+Math.random()*.3))));
 e.hp-=dealt;s.hp-=taken;dutyNote(action==='evade'?`Your escape was spotted. You take ${taken} damage but reach safety.`:`${action==='jutsu'?'Spirit strike':'Weapon strike'}: dealt ${dealt}, took ${taken} damage.`);
 const killed=e.hp===0,died=s.hp===0;if(killed){s.kills++;j.bonusCoins+=50;j.bonusXp+=10;dutyNote('Attacker killed · +1 Kill. Bonus: 50 Copper and 10 XP on completion.')}
 if(died){s.deaths++;s.losses++;failDuty('You were killed on duty · +1 Death. Visit the doctor.');return true}
 if(killed){s.wins++;finishDutyEvent()}else if(action==='evade')finishDutyEvent();return true;
}
claimDuty=function(){advanceDuty();const j=s.duty;if(!j||j.event||j.stage<3)return false;const d=dutyTypes.find(d=>d.id===j.id);if(j.elapsed<d.duration)return false;const coins=d.coins+j.bonusCoins,xp=d.xp+j.bonusXp;s.lastDuty={name:d.name,success:true,text:`Assignment complete: ${coins} Copper and ${xp} XP earned.`,journal:j.journal};s.duty=null;s.dutiesDone++;gain(xp,coins);log(s.lastDuty.text);return true};
function dutyEventHTML(j){const e=j.event,scene=DUTY_SCENES[j.id];if(!e)return `<div class="duty-travel"><div class="eyebrow">ON ASSIGNMENT</div><h3>${j.elapsed>=dutyTypes.find(d=>d.id===j.id).duration?'You made it back.':'Moving through '+scene.place.toLowerCase()+'…'}</h3><p>${j.elapsed>=dutyTypes.find(d=>d.id===j.id).duration?'Collect your duty reward below.':'Stay alert. Your next checkpoint may reveal danger or an opportunity.'}</p></div>`;
 const button=(action,label,disabled=false)=>`<button class="${action==='evade'||action==='continue'?'outline':'gold'}" data-system="dutyChoice" data-id="${action}" ${disabled?'disabled':''}>${label}</button>`;
 if(e.type==='route')return `<div class="duty-event"><span class="badge">DECISION · TIMER PAUSED</span><h3>Choose your approach</h3><p>${scene.intro}</p><div class="system-actions">${button('cautious','Scout ahead · −35% incoming damage')}${button('bold','Direct route · +30 Copper')}</div></div>`;
 if(e.type==='discovery')return `<div class="duty-event"><span class="badge">DISCOVERY · TIMER PAUSED</span><h3>${scene.discovery}</h3><p>${scene.detail}</p><p>Investigate: 5 Spirit → +40 Copper and +8 XP on completion.</p><div class="system-actions">${button('investigate','Investigate · 5 Spirit',s.energy<5)}${button('continue','Secure area & continue')}</div></div>`;
 return `<div class="duty-event ambush" aria-live="polite"><span class="badge">AMBUSH · TIMER PAUSED</span><h3>${e.name}</h3><div class="duty-health"><span>${uiIcon(7)} You: ${s.hp} / ${maxHealth()} HP</span><span>Enemy: ${e.hp} / ${e.maxHp} HP</span></div><div class="bar"><i style="width:${e.hp/e.maxHp*100}%;background:#cf7065"></i></div><p>Each strike can deal up to <b>27 damage</b> to either fighter. Killing the attacker earns +50 Copper and +10 XP on completion.</p><div class="system-actions">${button('fight','Weapon strike',s.hp<=0)}${button('jutsu','Spirit strike · 8 Spirit',s.hp<=0||s.energy<8||!Object.values(s.tech).some(n=>n>0))}${button('evade','Evade · 70% clean escape',s.hp<=0)}</div><p class="muted">Weapon strikes cost no extra stamina. A failed evasion causes one hit, then you escape if you survive.</p>${s.hp<=0?'<button class="outline" data-tab="council">Visit the doctor</button>':''}</div>`;
}
dutiesView=function(){advanceDuty();const j=s.duty,d=j?dutyTypes.find(d=>d.id===j.id):null,scene=j?DUTY_SCENES[j.id]:null;$('#view').innerHTML=title('LIVE VILLAGE DUTIES','Choose your route. Face the unexpected. Bring your shinobi home.')+(j?`<article class="card live-duty"><div class="duty-heading">${entryArt(missions[scene.art])}<div><div class="eyebrow">${scene.place}</div><h2>${d.name}</h2><p>Reward: ${d.coins+j.bonusCoins} Copper · ${d.xp+j.bonusXp} XP</p></div></div><div class="duty-progress-label"><b id="duty-percent">${Math.floor(j.elapsed/d.duration*100)}%</b><span id="duty-time">${j.event?'Awaiting your decision':remaining(d.duration-j.elapsed)+' travel remaining'}</span></div><div id="duty-progress" class="duty-progress" role="progressbar" aria-label="Duty progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(j.elapsed/d.duration*100)}"><i style="width:${j.elapsed/d.duration*100}%"></i></div><div class="duty-checkpoints"><span>Departure</span><span>Ambush · 35%</span><span>Discovery · 70%</span><span>Return</span></div>${dutyEventHTML(j)}<div class="system-actions"><button class="gold" data-system="claimDuty" ${j.event||j.elapsed<d.duration?'disabled':''}>Collect duty reward</button><button class="text-button" data-system="retreatConfirm">Abandon duty</button></div><details class="duty-journal" open><summary>Patrol journal</summary>${j.journal.map(e=>`<p>${escapeHTML(e.text)}</p>`).join('')}</details></article>`:s.lastDuty?`<article class="card ${s.lastDuty.success?'duty-success':'duty-failure'}" role="status"><div class="eyebrow">${s.lastDuty.success?'MISSION ACCOMPLISHED':'DUTY ENDED'}</div><h2>${s.lastDuty.name}</h2><p>${escapeHTML(s.lastDuty.text)}</p>${!s.lastDuty.success&&s.hp<=0?'<button class="gold" data-tab="council">Visit the doctor</button>':''}<details><summary>Read duty report</summary>${s.lastDuty.journal.map(e=>`<p>${escapeHTML(e.text)}</p>`).join('')}</details></article>`:'')+`<div class="grid duty-options">${dutyTypes.map(d=>`<article class="card">${entryArt(missions[DUTY_SCENES[d.id].art])}<h3>${d.name}</h3><p>${d.desc}</p><p>${d.cost} Stamina · ${d.coins} Copper · ${d.xp} XP<br>Route choice, ambush and discovery included.</p><button class="gold" data-system="duty" data-id="${d.id}" ${j||s.hp<=0||s.stamina<d.cost?'disabled':''}>${s.hp<=0?'Visit the doctor first':'Start interactive duty'}</button></article>`).join('')}</div><p class="combat-note">Travel progresses while you are away but pauses at each encounter until you choose. No unattended combat damage. Leaving the page keeps your duty; abandoning it forfeits rewards. Patrol enemies are local NPCs, not real players.</p>`};
globalThis.extraViews.duties=dutiesView;
const dutyBaseAction=systemAction;
systemAction=function(action,id){if(action==='dutyChoice')return dutyChoice(id);if(action==='retreatConfirm'){open('<h2>Abandon this duty?</h2><p>You will lose the pending reward. Spent stamina is not refunded.</p><div class="system-actions"><button class="gold" data-system="retreatYes">Abandon duty</button><button class="outline" data-system="retreatNo">Keep going</button></div>');return false}if(action==='retreatYes'){$('#modal').close();return dutyChoice('retreat')}if(action==='retreatNo'){$('#modal').close();return false}return dutyBaseAction(action,id)};
function refreshDutyProgress(){const j=s.duty;if(!j||tab!=='duties')return;const d=dutyTypes.find(d=>d.id===j.id),p=Math.floor(j.elapsed/d.duration*100),bar=$('#duty-progress');if(!bar)return;bar.setAttribute('aria-valuenow',String(p));const fill=bar.querySelector('i');if(fill)fill.style.width=j.elapsed/d.duration*100+'%';$('#duty-percent').textContent=p+'%';$('#duty-time').textContent=j.event?'Awaiting your decision':remaining(d.duration-j.elapsed)+' travel remaining'}
setInterval(()=>{if(!s.duty)return;const changed=advanceDuty();if(tab==='duties'){if(changed)render();else refreshDutyProgress()}},1000);
migrateDuty();if(tab==='duties')render();
